'use strict';

/**
* Compute the integral of a double-precision floating-point strided array using the trapezoidal rule.
*
* ## Notes
*
* -   If `N <= 1`, both functions return `0.0`.
* -   The function computes an approximation of the integral using the trapezoidal rule whose accuracy depends on the sample point spacing and the smoothness of the underlying function.
*
* @module @stdlib/integrate/strided/dtrapezoid
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dtrapezoid = require( '@stdlib/integrate/strided/dtrapezoid' );
*
* var x = new Float64Array( [ 0.0, 1.0, 2.0, 3.0 ] );
* var y = new Float64Array( [ 0.0, 1.0, 4.0, 9.0 ] );
*
* var out = dtrapezoid( x.length, x, 1, y, 1 );
* // returns 9.5
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dtrapezoid = require( '@stdlib/integrate/strided/dtrapezoid' );
*
* var x = new Float64Array( [ 0.0, 1.0, 2.0, 3.0 ] );
* var y = new Float64Array( [ 0.0, 1.0, 4.0, 9.0 ] );
*
* var out = dtrapezoid.ndarray( x.length, x, 1, 0, y, 1, 0 );
* // returns 9.5
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dtrapezoid;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dtrapezoid = main;
} else {
	dtrapezoid = tmp;
}


// EXPORTS //

module.exports = dtrapezoid;

// exports: { "ndarray": "dtrapezoid.ndarray" }
